#!/usr/bin/env bash
# Question 1: Hardening review of ${Q1_NS}-apps. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/audit
mkdir -p /opt/course/audit
chown -R ubuntu:ubuntu /opt/course
kubectl delete namespace "${Q1_NS}-apps" --ignore-not-found --wait=true >/dev/null
kubectl create namespace "${Q1_NS}-apps" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-apps" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}-apps' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
# Which Pod does what changes on every run.
names=($(shuf -e api-gateway log-forwarder metrics-agent node-tuner backup-runner cache-warmer -n 6))
kubectl apply -f - <<EOF >/dev/null
apiVersion: v1
kind: Pod
metadata: { name: ${names[0]}, namespace: ${Q1_NS}-apps }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
      securityContext: { privileged: true }
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[1]}, namespace: ${Q1_NS}-apps }
spec:
  terminationGracePeriodSeconds: 1
  initContainers:
    - name: tune-sysctls
      image: busybox:1.36
      command: ["sh", "-c", "echo tuned"]
      securityContext: { privileged: true }
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[2]}, namespace: ${Q1_NS}-apps }
spec:
  terminationGracePeriodSeconds: 1
  hostNetwork: true
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[3]}, namespace: ${Q1_NS}-apps }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
      volumeMounts: [{ name: logs, mountPath: /host/log, readOnly: true }]
  volumes:
    - name: logs
      hostPath: { path: /var/log, type: Directory }
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[4]}, namespace: ${Q1_NS}-apps }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
      securityContext: { privileged: false, allowPrivilegeEscalation: false }
      volumeMounts: [{ name: scratch, mountPath: /scratch }]
  volumes:
    - name: scratch
      emptyDir: {}
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[5]}, namespace: ${Q1_NS}-apps }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
EOF
kubectl -n "${Q1_NS}-apps" wait --for=condition=Ready pod --all --timeout=180s >/dev/null
: "${Q1_NS}" "${Q1_NODE}"
